    function oldRun(conclusion, headSha) {
        var t = new Date(Date.now() - 3 * 60 * 60 * 1000).toISOString();
        return { status: 'completed', conclusion: conclusion, head_sha: headSha,
                 created_at: t, updated_at: t };
