        var sm = makeSmAgent(Object.assign(config('a', 'b'), {
            github: {
                items: [prItem(85, { labels: ['pr_approved', 'ai_validating'], headSha: 'sha333' })],
                pr: { number: 85, body: 'no closing keyword' },
