        var lr = (provider && provider.lastReview)
            ? provider.lastReview(item.prNumber) : null;
        var stale = !!(lr && lr.state === 'CHANGES_REQUESTED' && item.pr &&
                       item.pr.headSha && lr.commitId &&
                       lr.commitId !== item.pr.headSha);
