function matchesGuards(item, rule, provider, machineAuthor, owner, repoInfo) {
    var q = rule.query || {};
    var labels = item.labels || [];
    if (q.notLabels && q.notLabels.some(function (l) { return labels.indexOf(l) !== -1; })) {
