    ] };
    var sm = makeSmAgent(Object.assign(config('IstiN', 'flutter_agent_harness'), {
        github: { items: [prItem(1457, { branch: 'ai/gh-857', headSha: CUR,
                                        labels: ['pr_approved', 'ai_validating'] })],
                  commitCheckRuns: checkRuns,
