// gh-862: the merge-validated probe — the squash-merge attempt shared by
// the merge_pr action and the latch-skip arm-only/conclude paths. Live
// fa #1457 (rel-20261011-204928): the latch-skip armed ai_validating and
// continued, but the merge-validated rule runs EARLIER in the deployed
// rule order (sm_github.json index 6 vs validate-armed 11) — the arm
// landed after the merge window closed and the sweep ate it next tick
// (arm → 'stale arm swept' → re-arm ping-pong, merge never attempted).
// Returns 'merged' | 'latched' (un-approved green head — ai_validated
// latched, review follows). THROWS on a refused merge (anything but an
// explicit merged:true — fa pr-753 parity: the markers stay armed so the
// loop self-heals via unarm-stale → refresh → re-validate → retry).
function attemptMergeProbe(repoInfo, ticket, key) {
    // Verify the sticky pr_approved latch on the PR itself — an
    // un-approved green head latches ai_validated and defers to review
    // instead of merging (defense in depth for the rule guards).
    var gateRaw = github_get_pr({
        workspace: repoInfo.owner,
        repository: repoInfo.repo,
        pullRequestId: ticket.prNumber
    });
    var gatePr = {};
    try {
        gatePr = typeof gateRaw === 'string' ? JSON.parse(gateRaw) : (gateRaw || {});
    } catch (gateParseErr) { gatePr = {}; }
    var gateLabels = (gatePr.labels || []).map(function (l) {
        return (l && l.name) || l;
    });
    if (gateLabels.indexOf('pr_approved') === -1) {
        // Pre-review validation green: latch, unarm, review follows
        // (review-after-dev requires ai_validated).
        github_remove_label({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            number: ticket.prNumber, label: 'ai_validating'
        });
        github_add_labels({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            number: ticket.prNumber, labels: ['ai_validated']
        });
        console.log('  ✅ ' + key + ' validated (no approval yet) — ai_validated latched, review follows');
        return 'latched';
    }
    var mergeRaw = github_merge_pr({
        workspace: repoInfo.owner,
        repository: repoInfo.repo,
        pullRequestId: ticket.prNumber,
        mergeMethod: 'squash'
    });
    // The HTTP layer returns the raw body for error statuses (Java
    // parity) — a 405 "not mergeable" arrives as {"merged": false, ...}
    // with NO thrown error (live: fa pr-753). Anything but an explicit
    // merged:true is a failure: keep the markers so the loop self-heals.
    var mergeResp = {};
    try {
        mergeResp = typeof mergeRaw === 'string' ? JSON.parse(mergeRaw) : (mergeRaw || {});
    } catch (parseErr) { /* non-JSON body counts as refusal */ }
    if (mergeResp.merged !== true) {
        throw new Error('merge refused: ' +
            (typeof mergeRaw === 'string' ? mergeRaw : JSON.stringify(mergeRaw)));
    }
    try {
        github_remove_label({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            number: ticket.prNumber, label: 'ai_validating'
        });
        github_remove_label({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            number: ticket.prNumber, label: 'pr_approved'
        });
        github_remove_label({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            number: ticket.prNumber, label: 'ai_validated'
        });
    } catch (e2) { /* absent labels are fine post-merge */ }
    console.log('  🎉 ' + key + ' squash-merged');
    return 'merged';
}
