    }
    var mergeRaw = github_merge_pr({
        workspace: repoInfo.owner,
        repository: repoInfo.repo,
        pullRequestId: ticket.prNumber,
        mergeMethod: 'squash'
    });
    var mergeResp = {};
    try {
        mergeResp = typeof mergeRaw === 'string' ? JSON.parse(mergeRaw) : (mergeRaw || {});
